public class Ex08Suppressed {
    static class Resource implements AutoCloseable {
        final boolean failOnClose;
        Resource(boolean failOnClose) { this.failOnClose = failOnClose; }
        void work() throws Exception { throw new Exception("work failed"); }
        public void close() throws Exception {
            if (failOnClose) throw new Exception("close failed");
        }
    }
    public static void main(String[] args) {
        try (Resource r = new Resource(true)) {
            r.work();
        } catch (Exception e) {
            System.out.println("primary=" + e.getMessage());
            Throwable[] suppressed = e.getSuppressed();
            System.out.println("suppressed count=" + suppressed.length);
            for (Throwable t : suppressed) System.out.println("  suppressed=" + t.getMessage());
        }
    }
}
